catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }
    g_form.setDisplay('geo', false);
    g_form.setDisplay('company', false);
    g_form.setDisplay('province', false);
    g_form.setDisplay('city', false);
    g_form.setDisplay('address', false);
    g_form.setDisplay('postal_code', false);
    g_form.setDisplay('comment', false);
    g_form.setDisplay('requested_by', false);
    g_form.setDisplay('alternate_buyer', false);
    g_form.setDisplay('first_payment_approver_display', false);
    g_form.setMandatory('alternate_buyer', false);
    g_form.setMandatory('first_payment_approver_display', false);
    if (newValue == 1) {
        g_form.setDisplay('geo', true);
        g_form.setDisplay('company', true);
        g_form.setDisplay('alternate_buyer', false);
        g_form.setDisplay('first_payment_approver_display', false);
    }
    if (newValue == 2) {
        g_form.setDisplay('province', true);
        g_form.setDisplay('city', true);
        g_form.setDisplay('address', true);
    }
    else if (newValue == 3) {
        g_form.setDisplay('postal_code', true);
    }
    else if (newValue == 4) {
        g_form.setDisplay('comment', true);
    }
    else if (newValue == 5) {
        g_form.setDisplay('requested_by', true);
        g_form.setDisplay('alternate_buyer', true);
        g_form.setDisplay('first_payment_approver_display', true);
        // g_form.setMandatory('alternate_buyer', true);
        // g_form.setMandatory('first_payment_approver_display', true);
    }
}
